 { "edition": "47th, 2025", "dates": "Sept.", "theme": "", "visiteurs": "32,022", "exposants": "1,400" },
 { "edition": "Renamed 2009", "dates": "2009", "theme": "Becomes IFTM Top Resa (International French Travel Market)", "visiteurs": "", "exposants": "" },
 { "edition": "Move to Paris 2008", "dates": "2008", "theme": "Top Resa leaves Deauville for Paris Expo Porte de Versailles", "visiteurs": "", "exposants": "" },
