 { "edition": "2019", "dates": "November", "lieu": "Paris Expo Porte de Versailles", "visiteurs": "61,044", "exposants": "" },
 { "edition": "2013 (historic peak)", "dates": "November", "lieu": "Paris Expo Porte de Versailles", "visiteurs": "85,526", "exposants": "" },
