 rows={[
  { "edition": "2026 (1re sous Mobco)", "lieu": "Paris", "visiteurs": "10 000+ attendus", "exposants": "~250 attendus" },
  { "edition": "2024 (European Mobility Expo)", "lieu": "Strasbourg", "visiteurs": "~11 000", "exposants": "250" }
 ]}
